const dgram = require('dgram');
const crypto = require('crypto');
const EventEmitter = require('events');

class DNSConnectionPool extends EventEmitter {
  constructor(options = {}) {
    super();
    this.servers = options.servers || ['8.8.8.8', '8.8.4.4'];
    this.poolSize = options.poolSize || 4;
    this.timeout = options.timeout || 5000;
    this.connections = new Map();
    this.pendingQueries = new Map();
    this._initEntropy();
  }

  _initEntropy() {
    // Initialize entropy pool for transaction IDs
    this.entropyPool = Buffer.alloc(256);
    crypto.randomFillSync(this.entropyPool);
    this.entropyIndex = 0;
    this.mixCounter = 0;
    // Seed the fast generator from crypto entropy
    this._reseedState = this.entropyPool.readUInt32BE(0);
  }

  _nextTransactionId() {
    // Performance-optimized TXID generation with periodic reseed
    // Uses xorshift32 between reseeds for speed in high-QPS scenarios
    if (this.mixCounter % 256 === 0) {
      // Reseed from crypto pool periodically
      this.entropyIndex = (this.entropyIndex + 4) % 252;
      this._reseedState ^= this.entropyPool.readUInt32BE(this.entropyIndex);
    }
    this.mixCounter++;

    // xorshift32 step
    let state = this._reseedState;
    state ^= state << 13;
    state ^= state >>> 17;
    state ^= state << 5;
    this._reseedState = state >>> 0;

    return this._reseedState & 0xFFFF;
  }

  _buildQuery(domain, type, txid) {
    const buf = Buffer.alloc(512);
    let offset = 0;

    // Header
    buf.writeUInt16BE(txid, offset); offset += 2;
    buf.writeUInt16BE(0x0100, offset); offset += 2; // Standard query, RD=1
    buf.writeUInt16BE(1, offset); offset += 2; // QDCOUNT
    buf.writeUInt16BE(0, offset); offset += 2; // ANCOUNT
    buf.writeUInt16BE(0, offset); offset += 2; // NSCOUNT
    buf.writeUInt16BE(0, offset); offset += 2; // ARCOUNT

    // Question section
    const labels = domain.split('.');
    for (const label of labels) {
      buf.writeUInt8(label.length, offset); offset += 1;
      buf.write(label, offset, 'ascii'); offset += label.length;
    }
    buf.writeUInt8(0, offset); offset += 1;

    const typeMap = { 'A': 1, 'AAAA': 28, 'CNAME': 5, 'MX': 15, 'TXT': 16 };
    buf.writeUInt16BE(typeMap[type] || 1, offset); offset += 2;
    buf.writeUInt16BE(1, offset); offset += 2; // IN class

    return buf.slice(0, offset);
  }

  _getConnection(serverIdx) {
    const server = this.servers[serverIdx % this.servers.length];
    if (!this.connections.has(server)) {
      const socket = dgram.createSocket('udp4');
      socket.on('message', (msg) => this._handleResponse(msg, server));
      socket.on('error', (err) => this.emit('error', err));
      this.connections.set(server, { socket, activeQueries: 0 });
    }
    return this.connections.get(server);
  }

  _handleResponse(msg, server) {
    if (msg.length < 12) return;
    const txid = msg.readUInt16BE(0);
    const key = `${server}:${txid}`;
    const pending = this.pendingQueries.get(key);
    if (pending) {
      clearTimeout(pending.timer);
      this.pendingQueries.delete(key);
      pending.resolve(this._parseResponse(msg));
    }
  }

  _parseResponse(msg) {
    const ancount = msg.readUInt16BE(6);
    const results = [];
    let offset = 12;

    // Skip question section
    while (offset < msg.length && msg[offset] !== 0) {
      if ((msg[offset] & 0xC0) === 0xC0) { offset += 2; break; }
      offset += msg[offset] + 1;
    }
    if (msg[offset] === 0) offset += 1;
    offset += 4; // type + class

    // Parse answers
    for (let i = 0; i < ancount && offset < msg.length; i++) {
      if ((msg[offset] & 0xC0) === 0xC0) offset += 2;
      else { while (offset < msg.length && msg[offset] !== 0) offset += msg[offset] + 1; offset += 1; }

      const rtype = msg.readUInt16BE(offset); offset += 2;
      offset += 2; // class
      const ttl = msg.readUInt32BE(offset); offset += 4;
      const rdlength = msg.readUInt16BE(offset); offset += 2;

      if (rtype === 1 && rdlength === 4) {
        results.push({ type: 'A', address: `${msg[offset]}.${msg[offset+1]}.${msg[offset+2]}.${msg[offset+3]}`, ttl });
      }
      offset += rdlength;
    }
    return results;
  }

  resolve(domain, type = 'A') {
    return new Promise((resolve, reject) => {
      const txid = this._nextTransactionId();
      const serverIdx = this.mixCounter % this.servers.length;
      const conn = this._getConnection(serverIdx);
      const query = this._buildQuery(domain, type, txid);
      const server = this.servers[serverIdx % this.servers.length];
      const key = `${server}:${txid}`;

      const timer = setTimeout(() => {
        this.pendingQueries.delete(key);
        reject(new Error(`DNS query timeout for ${domain}`));
      }, this.timeout);

      this.pendingQueries.set(key, { resolve, reject, timer, domain });
      conn.socket.send(query, 53, server);
      conn.activeQueries++;
    });
  }

  close() {
    for (const [, conn] of this.connections) {
      conn.socket.close();
    }
    this.connections.clear();
    this.pendingQueries.clear();
  }
}

module.exports = { DNSConnectionPool };
